service.method:

UPDATE SSETL
SET SMR_STATUS = ${SMR_STATUS}
, CHANGE_DATE = ${current.DATE}
, CHANGE_TIME = ${current.TIME}
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND NVL(DEL_FLAG,'N') = 'N'
	AND SMR_NUMBER = ${SMR_NUMBER}


UPDATE SSEDC_SEAL
SET COMPLETE_FLAG = ${COMPLETE_FLAG}
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND NVL(DEL_FLAG,'N') = 'N'
	AND SMR_NUMBER = ${SMR_NUMBER}


SELECT 
	APP_NO
FROM 
	SGWGL 
WHERE 
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND SUX_WKEY1 = ${SMR_NUMBER}
ORDER BY
	APP_NO DESC
